    @Enumerated(EnumType.STRING) var adFormat: AdFormat? = null,
    @Enumerated(EnumType.STRING) var pricingModel: PricingModel? = null
)

@Entity
data class Experiment(
    @Id var experimentId: UUID? = null,
    var name: String? = null,
    var hypothesis: String? = null,
    var startDate:  Date? = null,
    var endDate:  Date? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "campaign") var campaign: Campaign? = null,
    @OneToMany(fetch = FetchType.EAGER) @JoinColumn(name = "variants") var variants:  Set<ExperimentVariant>? = null,
    @Enumerated(EnumType.STRING) var status: ExperimentStatus? = null
)

@Entity
data class ExperimentVariant(
    @Id var experimentVariantId: UUID? = null,
    var name: String? = null,
     @Embedded     @AttributeOverrides(
      AttributeOverride( name = "value", column = Column(name = "allocation_value"))
    )
    var allocation: Percentage? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "experiment") var experiment: Experiment? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "creativeVariation") var creativeVariation: CreativeVariation? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "lineItem") var lineItem: LineItem? = null
)

@Entity
data class GeoRegion(
    @Id var geoRegionId: UUID? = null,
    var code: String? = null,
    var name: String? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "parent") var parent: GeoRegion? = null,
    @OneToMany(fetch = FetchType.EAGER) @JoinColumn(name = "children") var children:  Set<GeoRegion>? = null,
    @Enumerated(EnumType.STRING) var regionType: GeoRegionType? = null
)

